// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amount1, uint256 amount2) public {
        vm.assume(amount1 <= VALUE_CAP);
        vm.assume(amount2 <= VALUE_CAP);
        vm.assume(actor != address(0));
        amount1 = bound(amount1, 1, 1 ether);
        amount2 = bound(amount2, 0, 1 ether);

        vm.deal(actor, amount1 + amount2);

        vm.prank(actor);
        c.addToBalance{value: amount1}();
        uint256 before = c.getBalance(actor);

        vm.prank(actor);
        c.addToBalance{value: amount2}();

        assertEq(c.getBalance(actor), before + amount2);
    }
}
